import os
import subprocess
import re

source_dir = "/root/papers/all/"
target_base = "/root/papers/"
folders = ["LLM", "trapped_ion_and_qc", "black_hole", "DNA", "music_history"]

# Keywords for each category
keywords = {
    "LLM": [r"LLM", r"Large Language Model", r"Transformer", r"Attention", r"GPT", r"BERT", r"Instruction Tuning", r"RLHF", r"Prompt"],
    "trapped_ion_and_qc": [r"Trapped Ion", r"Quantum Computing", r"Qubit", r"Entanglement", r"Quantum Logic", r"Ion Trap", r"Quantum Gate", r"Rabi", r"Lamb-Dicke"],
    "black_hole": [r"Black Hole", r"Event Horizon", r"Schwarzschild", r"General Relativity", r"Singularity", r"Hawking Radiation", r"Gravitational Wave", r"Kerr", r"AdS/CFT"],
    "DNA": [r"DNA", r"Genome", r"Nucleotide", r"Sequencing", r"Genetic", r"Chromosome", r"Mutation", r"Protein Synthesis", r"Nucleic Acid"],
    "music_history": [r"Music History", r"Composer", r"Symphony", r"Opera", r"Baroque", r"Classical Era", r"Romantic Era", r"Jazz", r"Beethoven", r"Mozart", r"Bach"]
}

def get_text(file_path):
    if file_path.endswith(".pdf"):
        try:
            # Extract first 2 pages for efficiency
            result = subprocess.run(["pdftotext", "-l", "2", file_path, "-"], capture_output=True, text=True)
            return result.stdout
        except:
            pass

    # Fallback for all files
    try:
        result = subprocess.run(["strings", file_path], capture_output=True, text=True)
        return result.stdout
    except:
        return ""

files = os.listdir(source_dir)
classification = {}

for filename in files:
    file_path = os.path.join(source_dir, filename)
    if os.path.isdir(file_path):
        continue

    text = get_text(file_path)
    found = False

    # Check each category except the last one first
    for folder in folders[:-1]:
        for kw in keywords[folder]:
            if re.search(kw, text, re.IGNORECASE):
                classification[filename] = folder
                found = True
                break
        if found:
            break

    if not found:
        # Check last category specifically, or just assign it
        for kw in keywords["music_history"]:
            if re.search(kw, text, re.IGNORECASE):
                classification[filename] = "music_history"
                found = True
                break

        if not found:
            classification[filename] = "music_history" # Default as requested

# Move files
for filename, folder in classification.items():
    src = os.path.join(source_dir, filename)
    dst = os.path.join(target_base, folder, filename)
    print(f"Moving {filename} to {folder}")
    os.rename(src, dst)

print("Done!")

