import os
import subprocess
import re
import zipfile

target_base = "/root/papers/"
folders = ["LLM", "trapped_ion_and_qc", "black_hole", "DNA", "music_history"]

# Keywords for each category
keywords = {
    "LLM": [r"\bLLM\b", r"Large Language Model", r"Transformer", r"Attention", r"GPT", r"BERT", r"Instruction Tuning", r"RLHF", r"Prompt"],
    "trapped_ion_and_qc": [r"Trapped Ion", r"Quantum Computing", r"Qubit", r"Entanglement", r"Quantum Logic", r"Ion Trap", r"Quantum Gate", r"Rabi", r"Lamb-Dicke", r"ion-photon"],
    "black_hole": [r"Black Hole", r"Event Horizon", r"Schwarzschild", r"General Relativity", r"Singularity", r"Hawking Radiation", r"Gravitational Wave", r"Kerr", r"AdS/CFT"],
    "DNA": [r"\bDNA\b", r"Genome", r"Nucleotide", r"Sequencing", r"Genetic", r"Chromosome", r"Mutation", r"Protein Synthesis", r"Nucleic Acid"],
    "music_history": [r"Music History", r"Composer", r"Symphony", r"Opera", r"Baroque", r"Classical Era", r"Romantic Era", r"Jazz", r"Beethoven", r"Mozart", r"Bach", r"Harmon", r"Musimetrics"]
}

def get_text(file_path):
    if file_path.endswith(".pdf"):
        try:
            result = subprocess.run(["pdftotext", "-l", "3", file_path, "-"], capture_output=True, text=True)
            return result.stdout
        except:
            pass
    elif file_path.endswith(".docx"):
        try:
            with zipfile.ZipFile(file_path, 'r') as z:
                content = z.read('word/document.xml').decode('utf-8')
                return ' '.join(re.findall(r'<w:t[^>]*>(.*?)</w:t>', content))
        except:
            pass
    elif file_path.endswith(".pptx"):
        try:
            text = []
            with zipfile.ZipFile(file_path, 'r') as z:
                for f in z.namelist():
                    if f.startswith('ppt/slides/slide'):
                        content = z.read(f).decode('utf-8')
                        text.extend(re.findall(r'<a:t[^>]*>(.*?)</a:t>', content))
            return ' '.join(text)
        except:
            pass

    # Fallback for all files
    try:
        result = subprocess.run(["strings", file_path], capture_output=True, text=True)
        return result.stdout
    except:
        return ""

# Collect all files from current target folders and 'all' folder
all_files = []
for root, dirs, files in os.walk(target_base):
    for f in files:
        if f.endswith((".pdf", ".docx", ".pptx")):
            all_files.append(os.path.join(root, f))

for file_path in all_files:
    filename = os.path.basename(file_path)
    text = get_text(file_path)
    found_folder = "music_history" # Default

    # Check each category except the last one first
    # Order matters: check more specific categories first?
    # Actually, trapped_ion and black_hole are quite specific.
    # LLM and DNA are also specific with \b.

    # New order for better accuracy
    check_order = ["trapped_ion_and_qc", "black_hole", "DNA", "LLM", "music_history"]

    found = False
    for folder in check_order[:-1]:
        for kw in keywords[folder]:
            if re.search(kw, text, re.IGNORECASE):
                found_folder = folder
                found = True
                break
        if found:
            break

    if not found:
        # Check music specifically
        for kw in keywords["music_history"]:
            if re.search(kw, text, re.IGNORECASE):
                found_folder = "music_history"
                found = True
                break

    dst_dir = os.path.join(target_base, found_folder)
    dst_path = os.path.join(dst_dir, filename)

    if file_path != dst_path:
        print(f"Moving {filename} from {os.path.dirname(file_path)} to {found_folder}")
        os.rename(file_path, dst_path)

print("Done!")

